public Session(SessionPool pool, string tenant)
{
    ArgumentNullException.ThrowIfNull(pool);          // .NET 6+ guard
    if (string.IsNullOrEmpty(tenant))
        throw new ArgumentException("tenant required", nameof(tenant));
    if (!pool.TryAcquire(tenant, out var conn))
        throw new PoolExhaustedException(tenant);     // refuse now, do not queue
    _conn = conn;
}
